def masks(grid):
    return {(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8}
def tile_shapes(cells):
    tiles=[]
    for r,c in cells:
        for dr in range(2):
            for dc in range(2):
                s={(r+rr,c+cc) for rr in range(2) for cc in range(2)}
                if s <= cells: tiles.append((s,1))
    # L triominoes from 2x2 minus one corner
    for r,c in cells:
        for dr in range(2):
            for dc in range(2):
                box={(r+rr,c+cc) for rr in range(2) for cc in range(2)}
                if box <= {(rr,cc) for rr in range(10) for cc in range(10)}:
                    for missing in box:
                        s=box-{missing}
                        if s<=cells:
                            # labels: missing TL=2, BL=3, TR=4, BR=5
                            mr,mc=missing
                            color={(r,c):2} # dummy
                            col={(r,c):2,(r+1,c):3,(r,c+1):4,(r+1,c+1):5}[missing]
                            tiles.append((s,col))
    uniq=[]
    seen=set()
    for s,col in tiles:
        k=(tuple(sorted(s)),col)
        if k not in seen: seen.add(k);uniq.append((s,col))
    return uniq
def covers(grid,lim=100000):
    cells=masks(grid); tiles=tile_shapes(cells); bycell={p:[] for p in cells}
    for t in tiles:
        for p in t[0]:bycell[p].append(t)
    out=[]
    def rec(rem,chosen):
        if not rem:
            out.append(chosen[:]);return
        p=min(rem,key=lambda p:sum(t[0]<=rem for t in bycell[p]))
        for t in bycell[p]:
            if t[0]<=rem:
                rec(rem-t[0],chosen+[t])
                if len(out)>=lim:return
    rec(cells,[])
    return out
