source='''def transform(grid):
    occupied = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    if not occupied:
        return [row[:] for row in grid]

    tiles = []
    for r in range(len(grid) - 1):
        for c in range(len(grid[0]) - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if box <= occupied:
                tiles.append((box, 1))
            for missing, color in (((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4), ((r + 1, c + 1), 5)):
                shape = box - {missing}
                if shape <= occupied:
                    tiles.append((shape, color))

    by_cell = {cell: [] for cell in occupied}
    for shape, color in tiles:
        for cell in shape:
            by_cell[cell].append((shape, color))

    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = solve(remaining - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    pieces = solve(occupied)
    result = [[0 for _ in row] for row in grid]
    for shape, color in pieces:
        for r, c in shape:
            result[r][c] = color
    return result
